package com.clanwars;


import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.ui.overlay.OverlayPosition;

@ConfigGroup("Clan Wars Countdown Timer")
public interface ClanWarsTimerConfig extends Config
{
	@ConfigItem(
			keyName = "enabled",
			name = "Enable overlay",
			description = "Show the Clan Wars countdown overlay"
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "wallTime",
			name = "Wall drop time",
			description = "Time in seconds before the walls drop",
			position = 1
	)
	default int wallTime()
	{
		return 120;
	}

	@ConfigItem(
			keyName = "soundEnabled",
			name = "Enable sound alert",
			description = "Play a sound before the walls drop",
			position = 2
	)
	default boolean soundEnabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "alertSeconds",
			name = "Alert at",
			description = "Seconds remaining when the sound alert should play",
			position = 3
	)
	default int alertSeconds()
	{
		return 10;
	}

	@Alpha
	@ConfigItem(
			keyName = "textColor",
			name = "Text color",
			description = "Color of the countdown text",
			position = 4
	)
	default Color textColor()
	{
		return Color.RED;
	}

	@ConfigItem(
			keyName = "compactDisplay",
			name = "Compact display",
			description = "Show only the remaining time, without the title and label",
			position = 5
	)
	default boolean compactDisplay()
	{
		return false;
	}

	@ConfigItem(
			keyName = "overlayPosition",
			name = "Overlay position",
			description = "Where the overlay is displayed",
			position = 6
	)
	default OverlayPosition overlayPosition()
	{
		return OverlayPosition.TOP_CENTER;
	}
}

package com.clanwars;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class ClanWarsTimerOverlay extends OverlayPanel
{
	private final ClanWarsTimerPlugin plugin;
	private final ClanWarsTimerConfig config;

	@Inject
	public ClanWarsTimerOverlay(ClanWarsTimerPlugin plugin, ClanWarsTimerConfig config)
	{
		this.plugin = plugin;
		this.config = config;

		setPosition(config.overlayPosition());
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enabled() || !plugin.isActive())
		{
			return null;
		}

		setPosition(config.overlayPosition());

		if (config.compactDisplay())
		{
			String timeRemaining = plugin.getFormattedTimeRemaining();
			int textWidth = graphics.getFontMetrics().stringWidth(timeRemaining);
			panelComponent.setPreferredSize(new Dimension(textWidth + 10, 0));

			panelComponent.getChildren().add(TitleComponent.builder()
					.text(timeRemaining)
					.color(config.textColor())
					.build());
		}
		else
		{
			panelComponent.setPreferredSize(new Dimension(ComponentConstants.STANDARD_WIDTH, 0));

			panelComponent.getChildren().add(TitleComponent.builder()
					.text("Clan Wars Timer")
					.color(Color.WHITE)
					.build());

			panelComponent.getChildren().add(LineComponent.builder()
					.left("Walls drop")
					.right(plugin.getFormattedTimeRemaining())
					.rightColor(config.textColor())
					.build());
		}

		return super.render(graphics);
	}
}

package com.clanwars;

import com.google.inject.Provides;
import java.util.Locale;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
        name = "ClanWars Countdown",
        description = "Shows a countdown until Clan Wars walls drop",
        tags = {"clan", "wars", "timer", "pvp"}
)
public class ClanWarsTimerPlugin extends Plugin
{
    private static final double TICK_LENGTH_SECONDS = 0.6d;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ClanWarsTimerOverlay overlay;

    @Inject
    private ClanWarsTimerConfig config;

    @Getter
    private int ticksRemaining = 0;

    @Getter
    private boolean active = false;

    private boolean alertPlayed = false;

    @Provides
    ClanWarsTimerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ClanWarsTimerConfig.class);
    }

    @Override
    protected void startUp()
    {
        reset();
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        reset();
    }

    private void reset()
    {
        active = false;
        ticksRemaining = 0;
        alertPlayed = false;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (isBattleStartMessage(event.getMessage()))
        {
            startTimer();
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if (!active)
        {
            return;
        }

        ticksRemaining--;

        int secondsRemaining = getSecondsRemaining();

        if (config.soundEnabled()
                && !alertPlayed
                && secondsRemaining == config.alertSeconds())
        {
            client.playSoundEffect(SoundEffectID.UI_BOOP);
            alertPlayed = true;
        }

        if (ticksRemaining <= 0)
        {
            active = false;
            ticksRemaining = 0;
            alertPlayed = false;
        }
    }

    int getSecondsRemaining()
    {
        return (int) Math.ceil(ticksRemaining * TICK_LENGTH_SECONDS);
    }

    String getFormattedTimeRemaining()
    {
        int secondsRemaining = getSecondsRemaining();
        return String.format("%d:%02d", secondsRemaining / 60, secondsRemaining % 60);
    }

    private boolean isBattleStartMessage(String message)
    {
        if (message == null)
        {
            return false;
        }

        String normalized = Text.removeTags(message)
                .replace('\u00A0', ' ')
                .toLowerCase(Locale.ENGLISH)
                .trim();

        boolean nonChallengerMessage = normalized.contains("has initiated a battle");

        boolean challengerMessage = normalized.contains("is being invited to join");

        return nonChallengerMessage || challengerMessage;
    }

    private void startTimer()
    {
        ticksRemaining = (int) Math.ceil(config.wallTime() / TICK_LENGTH_SECONDS);
        active = true;
        alertPlayed = false;
    }
}

package com.example;

import com.clanwars.ClanWarsTimerPlugin;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ClanWarsTimerPlugin.class);
		RuneLite.main(args);
	}
}
